function qrSVG(){let squares='';for(let y=0;y<25;y++)for(let x=0;x<25;x++){if((x*7+y*11+x*y)%5<2)squares+=`<rect x="${x+2}" y="${y+2}" width="1" height="1"/>`}const finder=(x,y)=>`<rect x="${x}" y="${y}" width="7" height="7"/><rect x="${x+1}" y="${y+1}" width="5" height="5" fill="white"/><rect x="${x+2}" y="${y+2}" width="3" height="3"/>`;return `<svg viewBox="0 0 29 29" role="img" aria-label="不可真实扫码的示例二维码"><rect width="29" height="29" fill="white"/><g fill="#0e1c13">${squares}${finder(2,2)}${finder(20,2)}${finder(2,20)}</g><rect x="8" y="12" width="13" height="6" rx="1" fill="white"/><text x="14.5" y="15.8" text-anchor="middle" font-family="Arial" font-weight="bold" font-size="2.7" fill="#143923">DEMO</text></svg>`}
function setQR(mode){state.qrState=mode;$('qr-scenario').value=mode;$('qr-box').setAttribute('aria-busy',String(mode==='loading'));$('qr-box').innerHTML=['waiting','scanned'].includes(mode)?qrSVG():`<div class="qr-placeholder">${icon(mode==='loading'?'loader':'refresh',mode==='loading'?'spin':'')}<span>${mode==='loading'?'正在获取示例二维码…':mode==='expired'?'二维码已过期':'示例获取失败'}</span></div>`;const msg={waiting:'请使用手机App扫码（此处为示例）',scanned:'已演示扫码，请确认模拟登录。',loading:'正在获取示例二维码…',expired:'示例二维码已过期，请刷新重试。',error:'模拟获取失败，点击刷新可重试。'};$('qr-status').textContent=msg[mode];$('qr-status').className='qr-status'+(mode==='error'?' error':'');$('qr-refresh').disabled=mode==='loading';$('qr-confirm').disabled=!['waiting','scanned'].includes(mode)}
function chooseFiles(files){if(state.batchIds.some(id=>isActive(byId(id))))return;const selected=Array.from(files).slice(0,32);const allowed=/\.(wav|mp3|m4a|flac|ogg|opus|aac|wma|mp4|mkv|webm|mov|avi|m4v)$/i;const valid=selected.filter(f=>f.size>0&&f.size<=512*1024*1024&&(f.type?.startsWith('audio/')||f.type?.startsWith('video/')||allowed.test(f.name)));state.files=valid.map(f=>({name:f.name,size:f.size}));if(state.files.length>1)$('reuse-model').checked=true;state.transcriptionTask=null;state.batchIds=[];if(valid.length!==selected.length)toast('已过滤空文件、超限文件或非音视频文件。');if(files.length>32)toast('最多选择32个文件，已保留前32项。');$('transcription-scenario').value='selected';renderTranscription()}
function demoFiles(){chooseFiles([{name:'山海旁白.wav',size:5284823,type:'audio/wav'},{name:'沿途采访.mp3',size:3198205,type:'audio/mp3'}]);toast('已加入示例文件，不读取任何真实文件内容。')}
function startTranscription(){if(state.batchIds.some(id=>isActive(byId(id))))return;let files=state.files;if($('transcription-source').value==='video'){const p=current();if(!p?.archived.includes(state.quality))return;files=[{name:p.title+'_'+state.quality+'p.mp4',size:128600000}]}if(!files.length)return;state.batchIds=[];for(const f of files){const j=createJob('transcription',{fileName:f.name,title:f.name,projectId:$('transcription-source').value==='video'?state.current:undefined,language:$('transcription-language').value});state.batchIds.push(j.id)}state.transcriptionTask=state.batchIds[0];$('transcription-scenario').value='running';renderAll()}
const exampleTranscript='00:00  沿着海岸，我们慢慢向前。山峦在左侧延伸，海面在远处铺开。\n\n00:08  这条公路连接着村落，也连接着那些没有赶路的时刻。\n\n00:16  我们想留下的，不只是抵达的地方，还有一路上的风与光。';
function renderTranscription(){const active=state.batchIds.some(id=>isActive(byId(id))),j=byId(state.transcriptionTask),videoSource=$('transcription-source').value==='video',p=current();$('local-upload').hidden=videoSource;$('archived-source-note').hidden=!videoSource;$('archived-source-note').textContent=p?.archived.includes(state.quality)?'使用已归档的示例视频：'+p.title:'请先在视频工作台下载并归档视频。';const names=state.files.map(f=>f.name);$('file-list').innerHTML=state.files.map((f,i)=>{const task=jobs.find(j=>j.kind==='transcription'&&j.fileName===f.name&&state.batchIds.includes(j.id));return `<div class="file-item">${icon('files')}<div class="file-name">${esc(f.name)}<small>${(f.size/1024/1024).toFixed(1)} MB · ${task?statusLabels[task.state]:'待提交'}</small></div><span>${task?.progress||0}${task?'%':''}</span><button class="icon-button ghost" data-remove-file="${i}" ${active?'disabled':''} aria-label="移除 ${esc(f.name)}">${icon('close')}</button></div>`}).join('');$('file-summary').textContent=videoSource?'使用当前已归档版本':state.files.length?`已选择 ${state.files.length} 个文件 · ${(state.files.reduce((a,f)=>a+f.size,0)/1024/1024).toFixed(1)} MB`:'尚未选择文件';buttonState('transcription-start',active?'转写中…':j?.state==='failed'?'重试转写':'开始转写',active?'loader':'wave',active||(videoSource?!p?.archived.includes(state.quality):!names.length),active);for(const id of ['choose-files','use-demo-files','file-input','transcription-source','transcription-language','reuse-model'])$(id).disabled=active;$('transcription-status').hidden=!j;$('transcription-status').className='pane-status'+(j?.state==='failed'?' error':'');if(j){const counts=state.batchIds.map(byId);const done=counts.filter(t=>t?.state==='completed').length;$('transcription-status').textContent=active&&state.batchIds.length>1?`批量任务：${done}/${state.batchIds.length} 已完成，其他文件继续排队处理。`:j.message;$('transcription-actions').innerHTML=isActive(j)?`<button class="small" data-cancel="${j.id}" ${j.state==='cancelling'?'disabled':''}>取消此转写任务</button>`:''}else $('transcription-actions').innerHTML='';$('transcript-result').hidden=j?.state!=='completed';$('transcript-file-title').textContent=j?`${j.fileName||j.title} · ${j.language==='en'?'英文':'中文'} · 示例结果`:'';$('transcript-text').textContent=exampleTranscript}
function renderTasks(){const expanded=[...document.querySelectorAll('.task-detail[open]')].map(e=>e.dataset.detailId);const visible=jobs.filter(j=>state.filter==='all'||state.filter==='active'&&isActive(j)||state.filter==='completed'&&j.state==='completed'||state.filter==='unfinished'&&['failed','cancelled'].includes(j.state));$('task-summary-count').textContent=`${jobs.length} 项示例任务 · ${runningCount()} 项进行中`;$('task-rows').innerHTML=visible.length?visible.map(j=>`<article class="task-row"><div class="task-row-main"><div class="task-name"><div class="task-type-icon">${icon(types[j.kind].icon)}</div><div><h3>${esc(j.title)}</h3><p>${types[j.kind].name} ${j.quality?'· '+j.quality+'P':''}${j.state==='failed'?' · '+esc(j.message):''}</p></div></div><div class="task-status ${esc(j.state)}">${icon(j.state==='completed'?'check':j.state==='failed'?'alert':j.state==='cancelled'?'stop':isActive(j)?'clock':'info')}<span>${statusLabels[j.state]}</span></div><span class="task-created">${esc(j.created)}</span><div class="task-row-actions">${isActive(j)?`<button data-cancel="${j.id}" ${j.state==='cancelling'?'disabled':''}>取消任务</button>`:''}${!isActive(j)?`<button data-view-task="${j.id}">${j.kind==='transcription'||j.kind==='subtitles'||j.kind==='analysis'?'查看结果':'打开项目'}</button>`:''}${['failed','cancelled'].includes(j.state)?`<button data-retry="${j.id}">重试</button>`:''}</div></div>${isActive(j)?`<div class="task-progress"><div class="operation-progress"><span style="width:${j.progress}%"></span></div><span>${j.state==='queued'?'排队':j.progress+'%'}</span></div>`:''}<details class="task-detail" data-detail-id="${j.id}" ${expanded.includes(j.id)?'open':''}><summary>任务详情</summary><p>示例ID：<span class="mono">${esc(j.id)}</span>${j.duration?' · 耗时 '+esc(j.duration):''}<br>${esc(j.message)}${j.errorCode?'<br>错误码：'+esc(j.errorCode):''}</p></details></article>`).join(''):'<div class="task-empty">此筛选下暂无示例任务</div>'}
function renderAll(){const focused=document.activeElement?.closest('[data-cancel],[data-retry],[data-view-task]');const focusData=focused?Object.entries(focused.dataset)[0]:null;const count=runningCount();$('global-count').textContent=count;$('global-dot').className='status-dot'+(count?' active':'');$('global-tasks').setAttribute('aria-label',`查看任务中心，${count}项进行中`);renderWorkspace();renderTranscription();renderTasks();if(focusData){const [key,val]=focusData;const attr=key.replace(/[A-Z]/g,c=>'-'+c.toLowerCase());const next=[...document.querySelectorAll('[data-'+attr+']')].find(e=>e.dataset[key]===val&&!e.disabled&&e.getClientRects().length);if(next)next.focus({preventScroll:true})}if($('cache-dialog').open){$('cache-confirm').disabled=count>0;$('cache-warning').textContent=count?'有任务正在运行，暂不能演示清理；请等待完成或取消。':'预览保护范围与正式功能一致；本次只模拟确认。'}}
function viewTask(id){const j=byId(id);if(!j)return;if(j.kind==='transcription'){state.transcriptionTask=id;navigate('transcription')}else{if(j.projectId)setProject(j.projectId);navigate('workspace');if(j.kind==='subtitles'){projects[j.projectId].subTask=id;setTab('subtitles')}else if(j.kind==='analysis'){projects[j.projectId].analysisTask=id;setTab('analysis')}else{projects[j.projectId].archiveTask=id;setTab('video')}renderAll()}}
function retry(id){const j=byId(id);if(!j)return;const n=createJob(j.kind,{projectId:j.projectId,quality:j.quality,scope:j.scope,episodeIndices:j.episodeIndices,fileName:j.fileName,language:j.language});if(j.kind==='video')projects[j.projectId].archiveTask=n.id;if(j.kind==='subtitles')projects[j.projectId].subTask=n.id;if(j.kind==='analysis')projects[j.projectId].analysisTask=n.id;if(j.kind==='transcription'){state.batchIds=[n.id];state.transcriptionTask=n.id}renderAll()}
function exportPreview(type){$('export-title').textContent=type==='cover'?'另存封面':`另存 ${type.toUpperCase()} 副本`;$('export-content').textContent=type==='cover'?'文件：山海封面.jpg\n来源：AI生成的示例画面\n操作：保存独立副本，不改变项目归档。':type==='srt'?'1\n00:00:00,000 --> 00:00:08,000\n沿着海岸，我们慢慢向前。\n\n2\n00:00:08,000 --> 00:00:16,000\n这条公路连接着村落。\n\n（示例字幕，不是实际识别结果）':exampleTranscript;openModal('export-dialog')}
